---@field CellNode                      	UnityEngine.RectTransform
local UIBattlingWaveInfoPanel = Class('UIBattlingWaveInfoPanel')

------------ LifeCycle ------------

function UIBattlingWaveInfoPanel:__init()
    self:CleanField()
end

function UIBattlingWaveInfoPanel:__delete()
   self:CleanField()
end

function UIBattlingWaveInfoPanel:CleanField()
    self.waveCell, self.txtWNum = nil, nil
    self.roundCell, self.txtRNum = nil, nil 
    self.timerCell, self.txtTNum, self.stTxtNum, self.stTxtDesc, self.warningNode = nil, nil, nil, nil, nil
    self.listWaveNode = nil
    self.coSwitchWave = nil
end


function UIBattlingWaveInfoPanel:Awake()
    self:InitComponent()
end

function UIBattlingWaveInfoPanel:Start()
end

function UIBattlingWaveInfoPanel:OnDestroy()
    if not isNull(self.coSwitchWave) then
        cs_coroutine.stop(self.coSwitchWave)
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

