------------ Init ------------

function UIBattlingWaveInfoPanel:InitComponent()
    xTry(function()
        self.roundCell, self.txtRNum = self:InitCell("ROUND")
        self:SetBattleRoundsValue(1)
        -- ---波次显示UIType_PVP_PVE
        -- if BattleInfo.gameMode == Constants.GameMode.PVE 
        --         and UIBattleSettingMgr.UIType ~= UIBattleSettingMgr.EnumUIType.PVP then
            self:InitWaveNode()
        -- end
        --if UIBattleSettingMgr.showRemainTime then
        --    self.timerCell, self.txtTNum, self.stTxtNum, self.stTxtDesc, self.warningNode = self:InitTimerCell()
        --end
    end)
end

function UIBattlingWaveInfoPanel:InitWaveNode()
    self.listWaveNode = {}
    local waveNumMax = checkNumber(UIBattlingDataMgr:GetBattleFieldWaveMax())
    for i = 1, waveNumMax do
        local node = KTool.Instantiate(self.RootWavePoint.gameObject, self.WaveNode.gameObject)
        KTool.SetActive(node.gameObject, true)
        local animator = KTool.GetComponent(node, typeof(Animator))
        local transNode =  node.transform
        animator:Play(i <= 1 and ANIMATION_LIST_WAVE_NODE.Activation or ANIMATION_LIST_WAVE_NODE.Dark)
        if i >= waveNumMax then
            local nodeLine = transNode:Find("ImgLine")
            local nodeLine2 = transNode:Find("ImgLine2")
            KTool.SetActive(nodeLine.gameObject, false)
            KTool.SetActive(nodeLine2.gameObject, false)
        end
        table.insert(self.listWaveNode, animator)
    end
    if self.listWaveNode and table.count(self.listWaveNode) == 1 then
        KTool.SetActive(self.RootWavePoint.gameObject, false)
    end
end

function UIBattlingWaveInfoPanel:PlayInitAnimation()
    for i, animator in ipairs(self.listWaveNode) do
        animator:Play(i <= 1 and ANIMATION_LIST_WAVE_NODE.Activation or ANIMATION_LIST_WAVE_NODE.Dark)
    end
end

function UIBattlingWaveInfoPanel:InitCell(desc)
    local goCell = self.CellNode.gameObject
    local transCell = goCell.transform
    transCell:Find("DescText").gameObject:GetComponent(typeof(TextMeshProUGUI)).text = desc
    local txtNum = transCell:Find("Txt_Num").gameObject:GetComponent(typeof(Text))
    KTool.SetActive(goCell,true)
    return goCell, txtNum
end

function UIBattlingWaveInfoPanel:InitTimerCell()
    local goCell = KTool.Instantiate(self.controller.gameObject, self.PVPTimerNode.gameObject)
    local transCell = goCell.transform
    local txtNum = transCell:Find("Txt_Num").gameObject:GetComponent(typeof(TextMeshProUGUI))
    local stTxtNum = txtNum.gameObject:GetComponent(typeof(UISwitchTextMeshPro))
    local stTxtDesc = transCell:Find("DescText").gameObject:GetComponent(typeof(UISwitchText))
    local goWarningNode = transCell:Find("WarningNode").gameObject
    KTool.SetActive(goCell,true)
    return goCell, txtNum, stTxtNum, stTxtDesc, goWarningNode
end

