---SetWaveInfo
---设置波次信息
---@param waveNow integer @ 当前波次数
function UIBattlingWaveInfoPanel:SetWaveInfo(waveNow)
    -- print("->UIBattlingWaveInfoPanel:SetWaveInfo", waveNow)
    xTry(function()
        if isNull(self.listWaveNode) or #self.listWaveNode < 1 then return end
        waveNow = checkNumber(waveNow)
        local indexExWave = checkNumber(waveNow - 1)
        if isNull(self.listWaveNode[indexExWave]) then return end
        self.coSwitchWave = cs_coroutine.start(function()
            self.listWaveNode[indexExWave]:Play(ANIMATION_LIST_WAVE_NODE.Switch)
            cs_coroutine.yield_return(WaitForSeconds(0.25))
            self.listWaveNode[waveNow]:Play(ANIMATION_LIST_WAVE_NODE.Activation)
        end)
    end)
end

---SetBattleRoundsValue
---设置 战局回合数显示
---@param valueNow integer @ 回合数
function UIBattlingWaveInfoPanel:SetBattleRoundsValue(valueNow)
    xTry(function()
        if IsNull(self.roundCell) then return end
        if IsNull(self.txtRNum) then return end
        local roundMax = UIBattlingDataMgr:GetBattleRoundsMax()
        if roundMax and roundMax > 99 then
            self.txtRNum.text = string.format("%d/∞", valueNow or 0)
        else
            self.txtRNum.text = string.format("%d/%d", valueNow or 0, UIBattlingDataMgr:GetBattleRoundsMax() or 0)
        end
    end)
end

function UIBattlingWaveInfoPanel:SetWaveInfoState(state)
    KTool.SetActive(self.RootWavePoint.gameObject, state)
end

function UIBattlingWaveInfoPanel:SetRoundInfoState(state)
    if isNull(self.roundCell) then return end
    KTool.SetActive(self.roundCell.gameObject, state)
end
------------ Function ------------

return UIBattlingWaveInfoPanel
